1	import {
2		digestClosure,
3		type ExpectedHead,
4		type GenerationId,
5		type GenerationRecord,
6		type GenerationRef,
7		parseBlobDigest,
8		parseClosureDigest,
9		parseGenerationId,
10		parseHeadRevision,
11		parseStorageObjectId,
12		type PresentHead,
13		type StorageObjectId,
14	} from "@ts-drp/storage";
15	
16	const LOCAL_ONLY_POLICY_DIGEST = "53775c5c1ee01e346f588966d6e7acb876df2bd8b2abcbe2b2591f216f7d4d9b";
17	const HEX_DIGEST = /^[0-9a-f]{64}$/u;
18	
19	export const CLOSED_EPOCH_CLEANUP_REFUSALS = Object.freeze([
20		"D109A_QC_INVALID",
21		"D109A_ADOPTION_INVALID",
22		"D109A_HEAD_MISMATCH",
23		"D109A_REVISION_STALE",
24		"D109A_IDENTITY_INVALID",
25		"D109A_LINEAGE_INVALID",
26		"D109A_ROLLBACK_INSUFFICIENT",
27		"D109A_SNAPSHOT_MISSING",
28		"D109A_POLICY_UNSUPPORTED",
29		"D109A_OUTBOX_INCOMPLETE",
30	] as const);
31	
32	export type ClosedEpochCleanupRefusal = (typeof CLOSED_EPOCH_CLEANUP_REFUSALS)[number];
33	
34	export type ClosedEpochCleanupPlan = Readonly<{
35		readonly activeGenerationId: GenerationId;
36		readonly availabilityPolicyDigest: string;
37		readonly closedEpoch: number;
38		readonly expectedHead: PresentHead;
39		readonly issuance: Readonly<{
40			readonly lineage: Readonly<{ readonly exhausted: boolean; readonly next: number }>;
41			readonly prunedThroughAuthorSequence: number | null;
42			readonly scope: Readonly<{ readonly author: string; readonly objectId: StorageObjectId }>;
43			readonly throughAuthorSequence: number;
44		}>;
45		readonly lineageFloor: Readonly<{
46			readonly deleteGenerationIds: readonly GenerationId[];
47			readonly expectedBaseExpectedHead: ExpectedHead;
48			readonly generationId: GenerationId;
49			readonly replacementBaseExpectedHead: Readonly<{
50				readonly kind: "none";
51				readonly objectId: StorageObjectId;
52			}>;
53		}>;
54		readonly objectId: StorageObjectId;
55		readonly rollbackGenerationIds: readonly [GenerationId, GenerationId];
56	}>;
57	
58	export type ClosedEpochCleanupPlanningResult =
59		| Readonly<{ readonly ok: false; readonly reason: ClosedEpochCleanupRefusal }>
60		| Readonly<{ readonly ok: true; readonly plan: ClosedEpochCleanupPlan }>;
61	
62	type CapturedInput = Readonly<{
63		readonly adoption: Readonly<Record<string, unknown>>;
64		readonly availabilityPolicyDigest: unknown;
65		readonly close: Readonly<Record<string, unknown>>;
66		readonly expectedHead: unknown;
67		readonly generations: readonly unknown[];
68		readonly issuance: Readonly<Record<string, unknown>>;
69		readonly snapshot: Readonly<Record<string, unknown>>;
70	}>;
71	
72	type CopiedGeneration = Readonly<{
73		readonly baseExpectedHead: ExpectedHead;
74		readonly closure: readonly GenerationRef[];
75		readonly closureDigest: GenerationRecord["closureDigest"];
76		readonly generationId: GenerationId;
77		readonly objectId: StorageObjectId;
78		readonly state: GenerationRecord["state"];
79	}>;
80	
81	function refused(reason: ClosedEpochCleanupRefusal): ClosedEpochCleanupPlanningResult {
82		return Object.freeze({ ok: false as const, reason });
83	}
84	
85	function record(value: unknown): value is Readonly<Record<string, unknown>> {
86		if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
87		const prototype = Object.getPrototypeOf(value);
88		return prototype === Object.prototype || prototype === null;
89	}
90	
91	function exactKeys(value: Readonly<Record<string, unknown>>, keys: readonly string[]): boolean {
92		const actual = Object.keys(value).sort();
93		const expected = [...keys].sort();
94		return actual.length === expected.length && actual.every((key, index) => key === expected[index]);
95	}
96	
97	function captureInput(value: unknown): CapturedInput | undefined {
98		if (
99			!record(value) ||
100			!exactKeys(value, [
101				"adoption",
102				"availabilityPolicyDigest",
103				"close",
104				"expectedHead",
105				"generations",
106				"issuance",
107				"snapshot",
108			]) ||
109			!record(value.adoption) ||
110			!record(value.close) ||
111			!record(value.issuance) ||
112			!record(value.snapshot) ||
113			!Array.isArray(value.generations)
114		) {
115			return undefined;
116		}
117		return Object.freeze({
118			adoption: value.adoption,
119			availabilityPolicyDigest: value.availabilityPolicyDigest,
120			close: value.close,
121			expectedHead: value.expectedHead,
122			generations: value.generations,
123			issuance: value.issuance,
124			snapshot: value.snapshot,
125		});
126	}
127	
128	function copiedObjectId(value: unknown): StorageObjectId | undefined {
129		return typeof value === "string" && parseStorageObjectId(value).ok ? (value as StorageObjectId) : undefined;
130	}
131	
132	function copiedGenerationId(value: unknown): GenerationId | undefined {
133		return typeof value === "string" && parseGenerationId(value).ok ? (value as GenerationId) : undefined;
134	}
135	
136	function copiedRef(value: unknown): GenerationRef | undefined {
137		if (
138			!record(value) ||
139			!exactKeys(value, ["byteLength", "digest"]) ||
140			!Number.isSafeInteger(value.byteLength) ||
141			Number(value.byteLength) < 1 ||
142			typeof value.digest !== "string" ||
143			!parseBlobDigest(value.digest).ok
144		) {
145			return undefined;
146		}
147		return Object.freeze({ byteLength: Number(value.byteLength), digest: value.digest as GenerationRef["digest"] });
148	}
149	
150	function copiedExpectedHead(value: unknown, objectId: StorageObjectId): ExpectedHead | undefined {
151		if (!record(value)) return undefined;
152		if (exactKeys(value, ["kind", "objectId"]) && value.kind === "none" && copiedObjectId(value.objectId) === objectId) {
153			return Object.freeze({ kind: "none" as const, objectId });
154		}
155		if (
156			!exactKeys(value, ["closureDigest", "generationId", "kind", "objectId", "revision"]) ||
157			value.kind !== "present" ||
158			copiedObjectId(value.objectId) !== objectId ||
159			copiedGenerationId(value.generationId) === undefined ||
160			!Number.isSafeInteger(value.revision) ||
161			typeof value.closureDigest !== "string" ||
162			!parseClosureDigest(value.closureDigest).ok
163		) {
164			return undefined;
165		}
166		const revision = parseHeadRevision(Number(value.revision));
167		if (!revision.ok) return undefined;
168		return Object.freeze({
169			closureDigest: value.closureDigest as PresentHead["closureDigest"],
170			generationId: value.generationId as GenerationId,
171			kind: "present" as const,
172			objectId,
173			revision: revision.value,
174		});
175	}
176	
177	function copiedGeneration(value: unknown, objectId: StorageObjectId): CopiedGeneration | undefined {
178		if (
179			!record(value) ||
180			!exactKeys(value, ["baseExpectedHead", "closure", "closureDigest", "generationId", "objectId", "state"]) ||
181			copiedObjectId(value.objectId) !== objectId ||
182			copiedGenerationId(value.generationId) === undefined ||
183			typeof value.closureDigest !== "string" ||
184			!parseClosureDigest(value.closureDigest).ok ||
185			!Array.isArray(value.closure) ||
186			!(["Staged", "Complete", "Adopted", "Superseded", "Discarded"] as const).includes(
187				value.state as GenerationRecord["state"]
188			)
189		) {
190			return undefined;
191		}
192		const baseExpectedHead = copiedExpectedHead(value.baseExpectedHead, objectId);
193		if (baseExpectedHead === undefined) return undefined;
194		const closure: GenerationRef[] = [];
195		for (const candidate of value.closure) {
196			const ref = copiedRef(candidate);
197			if (ref === undefined) return undefined;
198			closure.push(ref);
199		}
200		return Object.freeze({
201			baseExpectedHead,
202			closure: Object.freeze(closure),
203			closureDigest: value.closureDigest as GenerationRecord["closureDigest"],
204			generationId: value.generationId as GenerationId,
205			objectId,
206			state: value.state as GenerationRecord["state"],
207		});
208	}
209	
210	function sameHeadExceptRevision(left: PresentHead, right: PresentHead): boolean {
211		return (
212			left.closureDigest === right.closureDigest &&
213			left.generationId === right.generationId &&
214			left.objectId === right.objectId
215		);
216	}
217	
218	function validClosure(generation: CopiedGeneration): boolean {
219		if (generation.closure.length === 0) return false;
220		const digests = generation.closure.map(({ digest }) => digest);
221		if (new Set(digests).size !== digests.length) return false;
222		const sorted = [...digests].sort();
223		if (!digests.every((digest, index) => digest === sorted[index])) return false;
224		const digest = digestClosure(generation.closure);
225		return digest.ok && digest.value === generation.closureDigest;
226	}
227	
228	function parentMatches(child: CopiedGeneration, parent: CopiedGeneration, expectedChildRevision: number): boolean {
229		return (
230			child.baseExpectedHead.kind === "present" &&
231			child.baseExpectedHead.objectId === parent.objectId &&
232			child.baseExpectedHead.generationId === parent.generationId &&
233			child.baseExpectedHead.closureDigest === parent.closureDigest &&
234			child.baseExpectedHead.revision === expectedChildRevision - 1
235		);
236	}
237	
238	function copiedGenerations(
239		values: readonly unknown[],
240		objectId: StorageObjectId
241	):
242		| Readonly<{ readonly byId: ReadonlyMap<GenerationId, CopiedGeneration>; readonly rows: readonly CopiedGeneration[] }>
243		| undefined {
244		const rows: CopiedGeneration[] = [];
245		const byId = new Map<GenerationId, CopiedGeneration>();
246		for (const value of values) {
247			const generation = copiedGeneration(value, objectId);
248			if (generation === undefined || byId.has(generation.generationId)) return undefined;
249			rows.push(generation);
250			byId.set(generation.generationId, generation);
251		}
252		return Object.freeze({ byId, rows: Object.freeze(rows) });
253	}
254	
255	function lineagePlan(
256		generations: Readonly<{
257			readonly byId: ReadonlyMap<GenerationId, CopiedGeneration>;
258			readonly rows: readonly CopiedGeneration[];
259		}>,
260		activeHead: PresentHead
261	):
262		| Readonly<{ readonly kind: "invalid" }>
263		| Readonly<{ readonly kind: "insufficient" }>
264		| Readonly<{
265				readonly kind: "plan";
266				readonly deleteGenerationIds: readonly GenerationId[];
267				readonly floor: CopiedGeneration;
268				readonly rollbackGenerationIds: readonly [GenerationId, GenerationId];
269		  }> {
270		const active = generations.byId.get(activeHead.generationId);
271		if (
272			active === undefined ||
273			active.state !== "Adopted" ||
274			active.closureDigest !== activeHead.closureDigest ||
275			!validClosure(active)
276		) {
277			return Object.freeze({ kind: "invalid" as const });
278		}
279		if (active.baseExpectedHead.kind !== "present") return Object.freeze({ kind: "insufficient" as const });
280		const first = generations.byId.get(active.baseExpectedHead.generationId);
281		if (first === undefined) return Object.freeze({ kind: "insufficient" as const });
282		if (first.baseExpectedHead.kind !== "present") return Object.freeze({ kind: "insufficient" as const });
283		const second = generations.byId.get(first.baseExpectedHead.generationId);
284		if (second === undefined) return Object.freeze({ kind: "insufficient" as const });
285		if (
286			new Set([active.generationId, first.generationId, second.generationId]).size !== 3 ||
287			first.state !== "Superseded" ||
288			second.state !== "Superseded" ||
289			!validClosure(first) ||
290			!validClosure(second) ||
291			!parentMatches(active, first, activeHead.revision) ||
292			!parentMatches(first, second, active.baseExpectedHead.revision)
293		) {
294			return Object.freeze({ kind: "invalid" as const });
295		}
296	
297		const retained = new Set([active.generationId, first.generationId, second.generationId]);
298		const prefix: CopiedGeneration[] = [];
299		const visited = new Set<GenerationId>();
300		let expectedRevision = first.baseExpectedHead.revision;
301		let cursor = second.baseExpectedHead;
302		while (cursor.kind === "present") {
303			if (visited.has(cursor.generationId)) return Object.freeze({ kind: "invalid" as const });
304			const generation = generations.byId.get(cursor.generationId);
305			if (
306				generation === undefined ||
307				generation.state !== "Superseded" ||
308				!validClosure(generation) ||
309				cursor.revision !== expectedRevision - 1 ||
310				cursor.closureDigest !== generation.closureDigest
311			) {
312				return Object.freeze({ kind: "invalid" as const });
313			}
314			visited.add(generation.generationId);
315			prefix.push(generation);
316			expectedRevision = cursor.revision;
317			cursor = generation.baseExpectedHead;
318		}
319		if (cursor.objectId !== activeHead.objectId) return Object.freeze({ kind: "invalid" as const });
320	
321		const outsideRetained = generations.rows.filter(({ generationId }) => !retained.has(generationId));
322		if (
323			outsideRetained.length !== prefix.length ||
324			outsideRetained.some(({ generationId }) => !visited.has(generationId)) ||
325			generations.rows.some(
326				(generation) =>
327					retained.has(generation.generationId) &&
328					generation.generationId !== second.generationId &&
329					generation.baseExpectedHead.kind === "present" &&
330					visited.has(generation.baseExpectedHead.generationId)
331			)
332		) {
333			return Object.freeze({ kind: "invalid" as const });
334		}
335	
336		return Object.freeze({
337			deleteGenerationIds: Object.freeze(prefix.map(({ generationId }) => generationId).sort()),
338			floor: second,
339			kind: "plan" as const,
340			rollbackGenerationIds: Object.freeze([first.generationId, second.generationId] as const),
341		});
342	}
343	
344	function validSnapshot(value: Readonly<Record<string, unknown>>): boolean {
345		return (
346			exactKeys(value, ["adopted", "manifestDigest"]) &&
347			value.adopted === true &&
348			typeof value.manifestDigest === "string" &&
349			HEX_DIGEST.test(value.manifestDigest)
350		);
351	}
352	
353	function copiedIssuance(
354		value: Readonly<Record<string, unknown>>,
355		objectId: StorageObjectId,
356		closedEpoch: number
357	): ClosedEpochCleanupPlan["issuance"] | undefined {
358		if (
359			!exactKeys(value, [
360				"complete",
361				"lineage",
362				"prunedThroughAuthorSequence",
363				"rows",
364				"scope",
365				"throughAuthorSequence",
366			]) ||
367			value.complete !== true ||
368			!record(value.lineage) ||
369			!exactKeys(value.lineage, ["exhausted", "next"]) ||
370			typeof value.lineage.exhausted !== "boolean" ||
371			!Number.isSafeInteger(value.lineage.next) ||
372			Number(value.lineage.next) < 0 ||
373			(value.lineage.exhausted === true && Number(value.lineage.next) !== Number.MAX_SAFE_INTEGER) ||
374			(value.prunedThroughAuthorSequence !== null &&
375				(!Number.isSafeInteger(value.prunedThroughAuthorSequence) || Number(value.prunedThroughAuthorSequence) < 0)) ||
376			!record(value.scope) ||
377			!exactKeys(value.scope, ["author", "objectId"]) ||
378			copiedObjectId(value.scope.objectId) !== objectId ||
379			typeof value.scope.author !== "string" ||
380			!HEX_DIGEST.test(value.scope.author) ||
381			!Number.isSafeInteger(value.throughAuthorSequence) ||
382			Number(value.throughAuthorSequence) < 0 ||
383			!Array.isArray(value.rows)
384		) {
385			return undefined;
386		}
387		const throughAuthorSequence = Number(value.throughAuthorSequence);
388		const lineage = Object.freeze({ exhausted: value.lineage.exhausted, next: Number(value.lineage.next) });
389		const prunedThroughAuthorSequence =
390			value.prunedThroughAuthorSequence === null ? null : Number(value.prunedThroughAuthorSequence);
391		const consumed =
392			lineage.next > throughAuthorSequence || (lineage.exhausted && lineage.next === throughAuthorSequence);
393		if (
394			!consumed ||
395			(prunedThroughAuthorSequence !== null &&
396				(prunedThroughAuthorSequence > throughAuthorSequence ||
397					!(
398						lineage.next > prunedThroughAuthorSequence ||
399						(lineage.exhausted && lineage.next === prunedThroughAuthorSequence)
400					)))
401		) {
402			return undefined;
403		}
404		const first = prunedThroughAuthorSequence === null ? 0 : prunedThroughAuthorSequence + 1;
405		const expectedRows = throughAuthorSequence - first + 1;
406		if (value.rows.length !== Math.max(0, expectedRows)) return undefined;
407		const seen = new Set<number>();
408		for (const candidate of value.rows) {
409			if (
410				!record(candidate) ||
411				!exactKeys(candidate, ["authorSequence", "epoch", "issued", "outbox", "publishState"]) ||
412				!Number.isSafeInteger(candidate.authorSequence) ||
413				Number(candidate.authorSequence) < first ||
414				Number(candidate.authorSequence) > throughAuthorSequence ||
415				!Number.isSafeInteger(candidate.epoch) ||
416				Number(candidate.epoch) !== closedEpoch ||
417				candidate.issued !== true ||
418				candidate.outbox !== true ||
419				candidate.publishState !== "published" ||
420				seen.has(Number(candidate.authorSequence))
421			) {
422				return undefined;
423			}
424			seen.add(Number(candidate.authorSequence));
425		}
426		for (let sequence = first; sequence <= throughAuthorSequence; sequence += 1) {
427			if (!seen.has(sequence)) return undefined;
428		}
429		return Object.freeze({
430			lineage,
431			prunedThroughAuthorSequence,
432			scope: Object.freeze({ author: value.scope.author, objectId }),
433			throughAuthorSequence,
434		});
435	}
436	
437	/**
438	 * Plans one closed-epoch cleanup without opening a store, mutating state, or scheduling work.
439	 * @param input - Detached facts already authenticated by the owning Phase-5/6a components.
440	 * @returns One deep-frozen plan or the first exact refusal in the closed precedence.
441	 */
442	export function planClosedEpochCleanup(input: unknown): ClosedEpochCleanupPlanningResult {
443		try {
444			const captured = captureInput(input);
445			if (captured === undefined) return refused("D109A_IDENTITY_INVALID");
446	
447			if (
448				!exactKeys(captured.close, ["closedEpoch", "commitQcRef", "objectId", "verified"]) ||
449				captured.close.verified !== true ||
450				!Number.isSafeInteger(captured.close.closedEpoch) ||
451				Number(captured.close.closedEpoch) < 0 ||
452				copiedRef(captured.close.commitQcRef) === undefined
453			) {
454				return refused("D109A_QC_INVALID");
455			}
456			const objectId = copiedObjectId(captured.close.objectId);
457			if (objectId === undefined) return refused("D109A_IDENTITY_INVALID");
458			const closedEpoch = Number(captured.close.closedEpoch);
459	
460			if (!exactKeys(captured.adoption, ["activeHead", "adopted"]) || captured.adoption.adopted !== true) {
461				return refused("D109A_ADOPTION_INVALID");
462			}
463			const activeHead = copiedExpectedHead(captured.adoption.activeHead, objectId);
464			if (activeHead?.kind !== "present") return refused("D109A_ADOPTION_INVALID");
465			const expectedHead = copiedExpectedHead(captured.expectedHead, objectId);
466			if (expectedHead?.kind !== "present") return refused("D109A_HEAD_MISMATCH");
467			if (!sameHeadExceptRevision(activeHead, expectedHead)) return refused("D109A_HEAD_MISMATCH");
468			if (activeHead.revision !== expectedHead.revision) return refused("D109A_REVISION_STALE");
469	
470			const generations = copiedGenerations(captured.generations, objectId);
471			if (generations === undefined) return refused("D109A_IDENTITY_INVALID");
472			const active = generations.byId.get(activeHead.generationId);
473			if (active === undefined || active.state !== "Adopted" || active.closureDigest !== activeHead.closureDigest) {
474				return refused("D109A_HEAD_MISMATCH");
475			}
476			const lineage = lineagePlan(generations, activeHead);
477			if (lineage.kind === "insufficient") return refused("D109A_ROLLBACK_INSUFFICIENT");
478			if (lineage.kind === "invalid") return refused("D109A_LINEAGE_INVALID");
479	
480			if (!validSnapshot(captured.snapshot)) return refused("D109A_SNAPSHOT_MISSING");
481			if (captured.availabilityPolicyDigest !== LOCAL_ONLY_POLICY_DIGEST) {
482				return refused("D109A_POLICY_UNSUPPORTED");
483			}
484			const issuance = copiedIssuance(captured.issuance, objectId, closedEpoch);
485			if (issuance === undefined) return refused("D109A_OUTBOX_INCOMPLETE");
486	
487			return Object.freeze({
488				ok: true as const,
489				plan: Object.freeze({
490					activeGenerationId: active.generationId,
491					availabilityPolicyDigest: LOCAL_ONLY_POLICY_DIGEST,
492					closedEpoch,
493					expectedHead: Object.freeze({ ...expectedHead }),
494					issuance,
495					lineageFloor: Object.freeze({
496						deleteGenerationIds: lineage.deleteGenerationIds,
497						expectedBaseExpectedHead: Object.freeze({ ...lineage.floor.baseExpectedHead }),
498						generationId: lineage.floor.generationId,
499						replacementBaseExpectedHead: Object.freeze({ kind: "none" as const, objectId }),
500					}),
501					objectId,
502					rollbackGenerationIds: lineage.rollbackGenerationIds,
503				}),
504			});
505		} catch {
506			return refused("D109A_IDENTITY_INVALID");
507		}
508	}
509

