421			const floor = byId.get(first.baseExpectedHead.generationId);
422			if (floor === undefined) corrupt("retained rollback lineage contained a gap");
423			if (first.generationId !== firstId || floor.generationId !== floorId) {
424				retry("planned rollback generations changed before reclamation");
425			}
426			if (
427				first.state !== "Superseded" ||
428				floor.state !== "Superseded" ||
429				!parentMatches(active, first, input.expectedHead.revision) ||
430				!parentMatches(first, floor, active.baseExpectedHead.revision)
431			) {
432				corrupt("retained rollback lineage was invalid");
433			}
434	
435			const retained = new Set([active.generationId, first.generationId, floor.generationId]);
436			const selected: GenerationRecord[] = [];
437			let replay = false;
438			let normalizedThisCall = false;
439			if (headsEqual(floor.baseExpectedHead, input.lineageFloor.expectedBaseExpectedHead)) {
440				normalizedThisCall = !headsEqual(
441					input.lineageFloor.expectedBaseExpectedHead,
442					input.lineageFloor.replacementBaseExpectedHead
443				);
444				let cursor = floor.baseExpectedHead;
445				let expectedRevision = first.baseExpectedHead.kind === "present" ? first.baseExpectedHead.revision : 0;
446				const visited = new Set<GenerationId>();
447				while (cursor.kind === "present") {
448					if (visited.has(cursor.generationId)) corrupt("reclamation prefix contained a cycle");
449					const generation = byId.get(cursor.generationId);
450					if (
451						generation === undefined ||
452						generation.state !== "Superseded" ||
453						cursor.objectId !== input.objectId ||
454						cursor.closureDigest !== generation.closureDigest ||
455						cursor.revision !== expectedRevision - 1
456					) {
457						corrupt("reclamation prefix contained a gap or invalid parent");
458					}
459					visited.add(generation.generationId);
460					selected.push(generation);
461					expectedRevision = cursor.revision;
462					cursor = generation.baseExpectedHead;
463				}
464				if (cursor.objectId !== input.objectId) corrupt("reclamation prefix terminated in another object");
465			} else if (headsEqual(floor.baseExpectedHead, input.lineageFloor.replacementBaseExpectedHead)) {
466				replay = true;
467				if (input.lineageFloor.deleteGenerationIds.some((generationId) => byId.has(generationId))) {
468					corrupt("normalized floor retained part of the requested prefix");
469				}
470			} else {
471				retry("lineage floor changed before reclamation");
472			}
473	
474			const selectedIds = selected.map(({ generationId }) => generationId).sort();
475			if (!replay && !sameIds(selectedIds, input.lineageFloor.deleteGenerationIds)) {
476				retry("requested generation prefix no longer matches the complete lineage");
477			}
478			const extras = target.filter(
479				({ generationId }) => !retained.has(generationId) && !selectedIds.includes(generationId)
480			);
481			if (extras.length !== 0) {
482				const requestedPrefix = new Set(input.lineageFloor.deleteGenerationIds);
483				if (
484					replay &&
485					extras.some(
486						({ baseExpectedHead }) =>
487							baseExpectedHead.kind === "present" && requestedPrefix.has(baseExpectedHead.generationId)
488					)
489				) {
490					corrupt("normalized replay retained a dangling parent into the reclaimed prefix");
491				}
492				retry("target generation set changed before reclamation");
493			}
494	
495			const selectedSet = new Set(selectedIds);
496			const deletePromotions = promotions.filter(
497				({ generationId, objectId }) => objectId === input.objectId && selectedSet.has(generationId)
498			);
499			const candidateDigests = new Set(deletePromotions.map(({ digest }) => digest));
500			const remainingGenerationReferences = new Set(
501				generations
502					.filter(({ generationId, objectId }) => objectId !== input.objectId || !selectedSet.has(generationId))
503					.flatMap(({ closure }) => closure.map(({ digest }) => digest))
504			);
505			const remainingPromotionReferences = new Set(
506				promotions
507					.filter(({ generationId, objectId }) => objectId !== input.objectId || !selectedSet.has(generationId))
508					.map(({ digest }) => digest)
509			);
510			const deleteBlobDigests = [...candidateDigests]
511				.filter((digest) => !remainingGenerationReferences.has(digest) && !remainingPromotionReferences.has(digest))
512				.sort();
513			const rewrittenGeneration = cloneGeneration({
514				...floor,
515				baseExpectedHead: input.lineageFloor.replacementBaseExpectedHead,
516			});
517			return Object.freeze({
518				deleteBlobDigests: Object.freeze(deleteBlobDigests),
519				deleteGenerationIds: Object.freeze(normalizedThisCall ? selectedIds : []),
520				deletePromotions: Object.freeze(normalizedThisCall ? deletePromotions : []),
521				floor: Object.freeze({
522					generation: cloneGeneration(floor),
523					normalizedThisCall,
524					rewrittenGeneration,
525				}),
526				input,
527			});
528		} catch (error) {
529			if (error instanceof AheReclamationError) throw error;
530			throw failure("AHE_RECLAMATION_CORRUPT", "native snapshot could not be inspected", error);
531		}
532	}
533	
534	/**
535	 * Constructs the detached immutable receipt after exact native row counts pass.
536	 * @param decision - Shared classifier decision used by the transaction.
537	 * @returns Frozen receipt containing actual writes for this call.
538	 */
539	export function createAheReclamationReceipt(decision: AheReclamationDecision): AheReclamationReceipt {
540		const { input } = decision;
541		return Object.freeze({
542			activeGenerationId: input.activeGenerationId,
543			availabilityPolicyDigest: input.availabilityPolicyDigest,
544			closedEpoch: input.closedEpoch,
545			deletedBlobDigests: Object.freeze([...decision.deleteBlobDigests]),
546			deletedGenerationIds: Object.freeze([...decision.deleteGenerationIds]),
547			deletedPromotionCount: decision.deletePromotions.length,
548			expectedHead: cloneHead(input.expectedHead) as PresentHead,
549			floor: Object.freeze({
550				expectedFormerBaseExpectedHead: cloneHead(input.lineageFloor.expectedBaseExpectedHead),
551				generationId: input.lineageFloor.generationId,
552				normalizedThisCall: decision.floor.normalizedThisCall,
553				replacementBaseExpectedHead: cloneHead(input.lineageFloor.replacementBaseExpectedHead) as Readonly<{
554					kind: "none";
555					objectId: StorageObjectId;
556				}>,
557			}),
558			objectId: input.objectId,
559			reclaimedGenerationIds: Object.freeze([...input.lineageFloor.deleteGenerationIds]),
560			rollbackGenerationIds: Object.freeze([...input.rollbackGenerationIds]) as readonly [GenerationId, GenerationId],
561		});
562	}
563	
564	/**
565	 * Creates one frozen lifecycle or substrate error without widening the code set.
566	 * @param code - Closed error code.
567	 * @param message - Diagnostic summary.
568	 * @param cause - Optional substrate cause.
569	 * @returns Frozen classified error.
570	 */
571	export function createAheReclamationError(
572		code: AheReclamationErrorCode,
573		message: string,
574		cause?: unknown
575	): AheReclamationError {
576		return failure(code, message, cause);
577	}
578

