1	import {
2		type AheDurableStore,
3		decodeGenerationRecordV1,
4		decodeHeadRecordV1,
5		encodeGenerationRecordV1,
6		type ExpectedHead,
7		type GenerationRecord,
8		parseStorageObjectId,
9	} from "@ts-drp/storage";
10	import {
11		AheReclamationError,
12		type AheReclamationMaintenance,
13		type AheReclamationPromotion,
14		type AheReclamationReceipt,
15		type AheReclamationSnapshot,
16		captureAheReclamationInput,
17		classifyAheReclamation,
18		createAheReclamationError,
19		createAheReclamationReceipt,
20	} from "@ts-drp/storage/maintenance";
21	
22	import { runInternalPrimaryDispatch } from "./primary-dispatch.js";
23	import {
24		PHASE_2D_BLOBS_STORE,
25		PHASE_2D_GENERATIONS_STORE,
26		PHASE_2D_OBJECTS_STORE,
27		PHASE_2D_PROMOTIONS_STORE,
28	} from "./schema-idb.js";
29	
30	export type BrowserAheReclamationCrashEdge =
31		| "after-floor-rewrite"
32		| "after-promotion-delete"
33		| "after-generation-delete"
34		| "after-blob-delete"
35		| "before-commit"
36		| "after-commit";
37	
38	export type BrowserAheReclamationCrashObserver = (
39		edge: BrowserAheReclamationCrashEdge,
40		transaction: IDBTransaction
41	) => void;
42	
43	export type BrowserAheReclamationCountFault =
44		| "blob delete"
45		| "floor rewrite"
46		| "generation delete"
47		| "promotion delete";
48	
49	export type BrowserAheReclamationLifecycle = Readonly<{
50		acquireRecoveryTurn(): (() => void) | Promise<() => void>;
51		finishOperation(): void;
52		isClosed(): boolean;
53		isPoisoned(): boolean;
54		latchPoison(reason: "NON_CANONICAL_RECORD"): unknown;
55		startOperation(): IDBDatabase | undefined;
56	}>;
57	
58	type TransactionOutcome = Readonly<{ ok: true }> | Readonly<{ cause: unknown; ok: false }>;
59	
60	const maintenanceByStore = new WeakMap<AheDurableStore, AheReclamationMaintenance>();
61	const crashObserverByStore = new WeakMap<AheDurableStore, BrowserAheReclamationCrashObserver>();
62	const countFaultByStore = new WeakMap<AheDurableStore, BrowserAheReclamationCountFault>();
63	
64	function rowProperty(value: unknown, key: string): unknown {
65		if (typeof value !== "object" || value === null) return undefined;
66		const descriptor = Object.getOwnPropertyDescriptor(value, key);
67		return descriptor !== undefined && "value" in descriptor ? descriptor.value : undefined;
68	}
69	
70	function bytes(value: unknown): Uint8Array {
71		if (!(value instanceof Uint8Array)) throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "row bytes invalid");
72		return new Uint8Array(value);
73	}
74	
75	function requestValue<T>(request: IDBRequest<T>): Promise<T> {
76		return new Promise((resolve, reject) => {
77			request.addEventListener("success", () => resolve(request.result), { once: true });
78			request.addEventListener("error", () => reject(request.error ?? new Error("IndexedDB request failed")), {
79				once: true,
80			});
81		});
82	}
83	
84	function transactionOutcome(transaction: IDBTransaction): Promise<TransactionOutcome> {
85		return new Promise((resolve) => {
86			let observedError: unknown;
87			transaction.addEventListener("complete", () => resolve({ ok: true }), { once: true });
88			transaction.addEventListener(
89				"abort",
90				() => resolve({ cause: transaction.error ?? observedError ?? new Error("transaction aborted"), ok: false }),
91				{ once: true }
92			);
93			transaction.addEventListener(
94				"error",
95				() => {
96					observedError ??= transaction.error ?? new Error("transaction failed");
97				},
98				{ once: true }
99			);
100		});
101	}
102	
103	function abortIfActive(transaction: IDBTransaction): void {
104		try {
105			transaction.abort();
106		} catch {
107			// Preserve the primary classified failure.
108		}
109	}
110	
111	async function expectKey(
112		store: AheDurableStore,
113		objectStore: IDBObjectStore,
114		key: IDBValidKey,
115		expected: "absent" | "present",
116		label: BrowserAheReclamationCountFault
117	): Promise<void> {
118		const value = await requestValue(objectStore.getKey(key));
119		const matches = expected === "present" ? value !== undefined : value === undefined;
120		if (!matches || countFaultByStore.get(store) === label) {
121			throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", `${label} count mismatch`);
122		}
123	}
124	
125	async function loadSnapshot(transaction: IDBTransaction, objectId: string): Promise<AheReclamationSnapshot> {
126		const parsedObjectId = parseStorageObjectId(objectId);
127		if (!parsedObjectId.ok) throw createAheReclamationError("AHE_RECLAMATION_INVALID_ARGUMENT", "object ID invalid");
128		const objectRow = await requestValue(transaction.objectStore(PHASE_2D_OBJECTS_STORE).get(objectId));
129		let head: ExpectedHead = { kind: "none", objectId: parsedObjectId.value };
130		const headRecord = rowProperty(objectRow, "record");
131		if (objectRow !== undefined && headRecord !== null && headRecord !== undefined) {
132			const decoded = decodeHeadRecordV1(bytes(headRecord));
133			if (!decoded.ok || decoded.value.objectId !== objectId) {
134				throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "head row was malformed or misbound");
135			}
136			head = decoded.value;
137		}
138	
139		const generationRows = await requestValue(transaction.objectStore(PHASE_2D_GENERATIONS_STORE).getAll());
140		const generations: GenerationRecord[] = [];
141		for (const row of generationRows) {
142			const decoded = decodeGenerationRecordV1(bytes(rowProperty(row, "record")));
143			if (
144				!decoded.ok ||
145				decoded.value.objectId !== rowProperty(row, "objectId") ||
146				decoded.value.generationId !== rowProperty(row, "generationId")
147			) {
148				throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "generation row was malformed or misbound");
149			}
150			generations.push(decoded.value);
151		}
152	
153		const promotionRows = await requestValue(transaction.objectStore(PHASE_2D_PROMOTIONS_STORE).getAll());
154		const promotions = promotionRows.map(
155			(row) =>
156				({
157					digest: rowProperty(row, "digest"),
158					generationId: rowProperty(row, "generationId"),
159					objectId: rowProperty(row, "objectId"),
160				}) as AheReclamationPromotion
161		);
162		const digests = [...new Set(promotions.map(({ digest }) => digest))];
163		const blobStore = transaction.objectStore(PHASE_2D_BLOBS_STORE);
164		const blobs = [];
165		for (const digest of digests) {
166			const row = await requestValue(blobStore.get(digest));
167			if (row !== undefined) blobs.push({ bytes: bytes(rowProperty(row, "bytes")), digest });
168		}
169		return { blobs, generations, head, promotions } as AheReclamationSnapshot;
170	}
171	
172	class BrowserAheReclamationMaintenance implements AheReclamationMaintenance {
173		public constructor(
174			private readonly store: AheDurableStore,
175			private readonly lifecycle: BrowserAheReclamationLifecycle,
176			private readonly databaseName: string
177		) {}
178	
179		public async reclaimClosedEpoch(input: unknown): Promise<AheReclamationReceipt> {
180			const captured = captureAheReclamationInput(input);
181			return runInternalPrimaryDispatch({
182				databaseName: this.databaseName,
183				identity: "ahe-reclamation:v1",
184				task: () => this.reclaimCaptured(captured),
185			});
186		}
187	
188		private async reclaimCaptured(
189			captured: ReturnType<typeof captureAheReclamationInput>
190		): Promise<AheReclamationReceipt> {
191			const database = this.lifecycle.startOperation();
192			if (database === undefined) {
193				throw createAheReclamationError("AHE_RECLAMATION_STORE_CLOSED", "store is closed");
194			}
195			const turn = this.lifecycle.acquireRecoveryTurn();
196			const release = typeof turn === "function" ? turn : await turn;
197			let transaction: IDBTransaction | undefined;
198			let completion: Promise<TransactionOutcome> | undefined;
199			let committed = false;
200			try {
201				if (this.lifecycle.isClosed()) {
202					throw createAheReclamationError("AHE_RECLAMATION_STORE_CLOSED", "store closed before reclamation");
203				}
204				if (this.lifecycle.isPoisoned()) {
205					throw createAheReclamationError("AHE_RECLAMATION_STORE_POISONED", "store is poisoned");
206				}
207				transaction = database.transaction(
208					[PHASE_2D_BLOBS_STORE, PHASE_2D_GENERATIONS_STORE, PHASE_2D_OBJECTS_STORE, PHASE_2D_PROMOTIONS_STORE],
209					"readwrite",
210					{ durability: "strict" }
211				);
212				completion = transactionOutcome(transaction);
213				if (transaction.durability !== "strict") {
214					throw createAheReclamationError("AHE_RECLAMATION_SUBSTRATE_FAILURE", "strict durability unavailable");
215				}
216				const decision = classifyAheReclamation(captured, await loadSnapshot(transaction, captured.objectId));
217				const observer = crashObserverByStore.get(this.store);
218				if (decision.floor.normalizedThisCall) {
219					const generationStore = transaction.objectStore(PHASE_2D_GENERATIONS_STORE);
220					const floorKey = [captured.objectId, captured.lineageFloor.generationId];
221					await expectKey(this.store, generationStore, floorKey, "present", "floor rewrite");
222					await requestValue(
223						generationStore.put({
224							generationId: captured.lineageFloor.generationId,
225							objectId: captured.objectId,
226							record: encodeGenerationRecordV1(decision.floor.rewrittenGeneration),
227						})
228					);
229					await expectKey(this.store, generationStore, floorKey, "present", "floor rewrite");
230					observer?.("after-floor-rewrite", transaction);
231				}
232				const promotionStore = transaction.objectStore(PHASE_2D_PROMOTIONS_STORE);
233				for (const promotion of decision.deletePromotions) {
234					const key = [promotion.objectId, promotion.generationId, promotion.digest];
235					await expectKey(this.store, promotionStore, key, "present", "promotion delete");
236					await requestValue(promotionStore.delete(key));
237					await expectKey(this.store, promotionStore, key, "absent", "promotion delete");
238				}
239				if (decision.floor.normalizedThisCall) observer?.("after-promotion-delete", transaction);
240				const generationStore = transaction.objectStore(PHASE_2D_GENERATIONS_STORE);
241				for (const generationId of decision.deleteGenerationIds) {
242					const key = [captured.objectId, generationId];
243					await expectKey(this.store, generationStore, key, "present", "generation delete");
244					await requestValue(generationStore.delete(key));
245					await expectKey(this.store, generationStore, key, "absent", "generation delete");
246				}
247				if (decision.floor.normalizedThisCall) observer?.("after-generation-delete", transaction);
248				const blobStore = transaction.objectStore(PHASE_2D_BLOBS_STORE);
249				for (const digest of decision.deleteBlobDigests) {
250					await expectKey(this.store, blobStore, digest, "present", "blob delete");
251					await requestValue(blobStore.delete(digest));
252					await expectKey(this.store, blobStore, digest, "absent", "blob delete");
253				}
254				if (decision.floor.normalizedThisCall) observer?.("after-blob-delete", transaction);
255	
256				const post = classifyAheReclamation(captured, await loadSnapshot(transaction, captured.objectId));
257				if (
258					post.floor.normalizedThisCall ||
259					post.deleteGenerationIds.length !== 0 ||
260					post.deletePromotions.length !== 0 ||
261					post.deleteBlobDigests.length !== 0
262				) {
263					throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "post-state was not a complete replay");
264				}
265				observer?.("before-commit", transaction);
266				transaction.commit();
267				const outcome = await completion;
268				if (!outcome.ok) throw outcome.cause;
269				committed = true;
270				observer?.("after-commit", transaction);
271				return createAheReclamationReceipt(decision);
272			} catch (error) {
273				if (!committed && transaction !== undefined) abortIfActive(transaction);
274				if (!committed && completion !== undefined) await completion;
275				if (error instanceof AheReclamationError) {
276					if (error.code === "AHE_RECLAMATION_CORRUPT") this.lifecycle.latchPoison("NON_CANONICAL_RECORD");
277					throw error;
278				}
279				throw createAheReclamationError("AHE_RECLAMATION_SUBSTRATE_FAILURE", "IndexedDB reclamation failed", error);
280			} finally {
281				release();
282				this.lifecycle.finishOperation();
283			}
284		}
285	}
286	
287	/**
288	 * Registers maintenance authority for one genuine IndexedDB facade.
289	 * @param store - Exact facade identity.
290	 * @param lifecycle - Owning facade lifecycle controls.
291	 * @param databaseName - Exact adapter-owned database identity.
292	 */
293	export function registerBrowserAheReclamationMaintenance(
294		store: AheDurableStore,
295		lifecycle: BrowserAheReclamationLifecycle,
296		databaseName: string
297	): void {
298		maintenanceByStore.set(store, new BrowserAheReclamationMaintenance(store, lifecycle, databaseName));
299	}
300	
301	/**
302	 * Resolves maintenance only for the registered facade identity.
303	 * @param store - Candidate facade identity.
304	 * @returns The identity-bound maintenance owner, if registered.
305	 */
306	export function browserAheReclamationMaintenanceForStore(
307		store: AheDurableStore
308	): AheReclamationMaintenance | undefined {
309		return maintenanceByStore.get(store);
310	}
311	
312	/**
313	 * Installs the maintenance-only worker-termination observer for a package-local test.
314	 * @param store - Exact registered IndexedDB facade.
315	 * @param observer - Fixed checkpoint observer.
316	 */
317	export function installBrowserAheReclamationCrashObserver(
318		store: AheDurableStore,
319		observer: BrowserAheReclamationCrashObserver
320	): void {
321		if (!maintenanceByStore.has(store)) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
322		crashObserverByStore.set(store, observer);
323	}
324	
325	/**
326	 * Installs one fixed maintenance-only count mismatch for a package-local browser test.
327	 * @param store - Exact registered IndexedDB facade.
328	 * @param fault - Fixed row-count category to misreport.
329	 */
330	export function installBrowserAheReclamationCountFault(
331		store: AheDurableStore,
332		fault: BrowserAheReclamationCountFault
333	): void {
334		if (!maintenanceByStore.has(store)) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
335		countFaultByStore.set(store, fault);
336	}
