1	import { decodeCanonical } from "@ts-drp/canonical";
2	import type { GenerationId, GenerationRef, PresentHead } from "@ts-drp/storage";
3	
4	import type { CreatorSuccessorLiveMaterial, CreatorSuccessorLiveSeed } from "./creator-successor-live.js";
5	
6	export type CreatorAdoptionIntent = Readonly<Record<never, never>>;
7	export type PreparedCreatorSuccessorAdoption = Readonly<Record<never, never>>;
8	export type StagedCreatorSuccessorAdoption = Readonly<Record<never, never>>;
9	
10	export interface CreatorAdoptionIntentMaterial {
11		readonly activation: CreatorSuccessorLiveSeed;
12		readonly candidateReferences: readonly GenerationRef[];
13		readonly exactCanonicalProjectionBytes: Uint8Array;
14		readonly generationId: GenerationId;
15		readonly pendingHead: PresentHead;
16		readonly pendingReferences: readonly GenerationRef[];
17		readonly predecessorLiveRef: GenerationRef;
18	}
19	
20	export interface PreparedCreatorSuccessorAdoptionMaterial {
21		readonly activation: CreatorSuccessorLiveMaterial;
22		readonly descriptor: Readonly<Record<string, unknown>>;
23		readonly exactCanonicalProjectionBytes: Uint8Array;
24		readonly head: PresentHead;
25	}
26	
27	export type PreparedCreatorSuccessorAdoptionInput = Omit<PreparedCreatorSuccessorAdoptionMaterial, "descriptor">;
28	
29	export interface StagedCreatorSuccessorAdoptionMaterial {
30		readonly descriptor: Readonly<Record<string, unknown>>;
31		readonly intent: CreatorAdoptionIntentMaterial;
32	}
33	
34	const custody = new WeakMap<
35		object,
36		Readonly<{ readonly material: CreatorAdoptionIntentMaterial; readonly owner: object }>
37	>();
38	const sealedFacts = new WeakMap<object, object>();
39	const preparedCustody = new WeakMap<
40		object,
41		Readonly<{ readonly material: PreparedCreatorSuccessorAdoptionInput; readonly owner: object }>
42	>();
43	const stagedCustody = new WeakMap<
44		object,
45		Readonly<{ readonly material: StagedCreatorSuccessorAdoptionMaterial; readonly owner: object }>
46	>();
47	
48	function copiedRef(ref: GenerationRef): GenerationRef {
49		return Object.freeze({ byteLength: ref.byteLength, digest: ref.digest });
50	}
51	
52	function copiedHead(head: PresentHead): PresentHead {
53		return Object.freeze({ ...head });
54	}
55	
56	function decodedDescriptor(bytes: Uint8Array): Readonly<Record<string, unknown>> {
57		const decoded = decodeCanonical(bytes);
58		if (decoded === null || typeof decoded !== "object" || Array.isArray(decoded)) {
59			throw new TypeError("prepared creator successor descriptor is invalid");
60		}
61		return Object.freeze(decoded as Record<string, unknown>);
62	}
63	
64	/**
65	 * Retains facts authenticated by a genuine close behind the internal module boundary.
66	 * @param owner - Genuine sealed close handle.
67	 * @param facts - Private detached close facts.
68	 * @returns Whether this was the first installation for the owner.
69	 */
70	export function installCreatorAdoptionFacts(owner: object, facts: object): boolean {
71		if (sealedFacts.has(owner)) return false;
72		sealedFacts.set(owner, facts);
73		return true;
74	}
75	
76	/**
77	 * Resolves private close facts for the verifier without exposing them on a public export.
78	 * @param owner - Candidate genuine sealed close handle.
79	 * @returns Private facts, or undefined for an unknown handle.
80	 */
81	export function resolveCreatorAdoptionFacts<T extends object>(owner: object): T | undefined {
82		return sealedFacts.get(owner) as T | undefined;
83	}
84	
85	/**
86	 * Revokes the predecessor's private verifier facts after successor activation.
87	 * @param owner - Genuine sealed predecessor handle.
88	 * @returns Whether private facts were present and revoked.
89	 */
90	export function revokeCreatorAdoptionFacts(owner: object): boolean {
91		return sealedFacts.delete(owner);
92	}
93	
94	/**
95	 * Creates one opaque, owner-bound, destructively consumable adoption intent.
96	 * @param owner - Genuine close handle that owns consumption.
97	 * @param material - Detached verified successor projection.
98	 * @returns Opaque intent with no serializable authority.
99	 */
100	export function createCreatorAdoptionIntent(
101		owner: object,
102		material: CreatorAdoptionIntentMaterial
103	): CreatorAdoptionIntent {
104		const intent = Object.freeze({}) as CreatorAdoptionIntent;
105		custody.set(
106			intent,
107			Object.freeze({
108				material: Object.freeze({
109					activation: material.activation,
110					candidateReferences: Object.freeze(material.candidateReferences.map(copiedRef)),
111					exactCanonicalProjectionBytes: Uint8Array.from(material.exactCanonicalProjectionBytes),
112					generationId: material.generationId,
113					pendingHead: copiedHead(material.pendingHead),
114					pendingReferences: Object.freeze(material.pendingReferences.map(copiedRef)),
115					predecessorLiveRef: copiedRef(material.predecessorLiveRef),
116				}),
117				owner,
118			})
119		);
120		return intent;
121	}
122	
123	/**
124	 * Consumes a genuine intent exactly once when presented by its bound close handle.
125	 * @param intent - Opaque candidate intent.
126	 * @param owner - Expected genuine close handle.
127	 * @returns Detached verified projection material, or undefined.
128	 */
129	export function consumeCreatorAdoptionIntent(
130		intent: unknown,
131		owner: unknown
132	): CreatorAdoptionIntentMaterial | undefined {
133		if (intent === null || typeof intent !== "object" || owner === null || typeof owner !== "object") return undefined;
134		const retained = custody.get(intent);
135		if (retained === undefined || retained.owner !== owner) return undefined;
136		custody.delete(intent);
137		return Object.freeze({
138			activation: retained.material.activation,
139			candidateReferences: Object.freeze(retained.material.candidateReferences.map(copiedRef)),
140			exactCanonicalProjectionBytes: Uint8Array.from(retained.material.exactCanonicalProjectionBytes),
141			generationId: retained.material.generationId,
142			pendingHead: copiedHead(retained.material.pendingHead),
143			pendingReferences: Object.freeze(retained.material.pendingReferences.map(copiedRef)),
144			predecessorLiveRef: copiedRef(retained.material.predecessorLiveRef),
145		});
146	}
147	
148	/**
149	 * Creates one opaque successor-preparation capability for the later activation owner.
150	 * @param owner - Genuine sealed close handle.
151	 * @param material - Authenticated durable successor result.
152	 * @returns Opaque process-local capability.
153	 */
