155		owner: object,
156		material: PreparedCreatorSuccessorAdoptionInput
157	): PreparedCreatorSuccessorAdoption {
158		const capability = Object.freeze({}) as PreparedCreatorSuccessorAdoption;
159		preparedCustody.set(
160			capability,
161			Object.freeze({
162				material: Object.freeze({
163					activation: material.activation,
164					exactCanonicalProjectionBytes: Uint8Array.from(material.exactCanonicalProjectionBytes),
