168			})
169		);
170		return capability;
171	}
172	
173	/**
174	 * Destructively consumes one genuine successor-preparation capability.
175	 * @param capability - Opaque candidate capability.
176	 * @param owner - Genuine sealed close owner.
177	 * @returns Detached successor material, or undefined.
178	 */
179	export function consumePreparedCreatorSuccessorAdoption(
180		capability: unknown,
181		owner: unknown
182	): PreparedCreatorSuccessorAdoptionMaterial | undefined {
183		if (capability === null || typeof capability !== "object" || owner === null || typeof owner !== "object") {
184			return undefined;
185		}
186		const retained = preparedCustody.get(capability);
187		if (retained === undefined || retained.owner !== owner) return undefined;
188		preparedCustody.delete(capability);
189		const exactCanonicalProjectionBytes = Uint8Array.from(retained.material.exactCanonicalProjectionBytes);
190		return Object.freeze({
191			activation: retained.material.activation,
192			descriptor: decodedDescriptor(exactCanonicalProjectionBytes),
193			exactCanonicalProjectionBytes,
194			head: copiedHead(retained.material.head),
195		});
