3	import {
4		assertDurableIssueScope,
5		copyDurableIssueScope,
6		DurableIssuanceInvalidArgumentError,
7		isClosedDurableIssuanceRecord,
8		isValidDurableAuthorSequence,
9	} from "./contract.js";
10	import type { DurableIssuanceError, DurableIssuanceStore, DurableIssueScope, DurableLineage } from "./types.js";
11	
12	const HEX_DIGEST = /^[0-9a-f]{64}$/u;
