30	export interface DurableIssuancePruningReceipt {
31		readonly closedEpoch: number;
32		readonly commitQcRef: Readonly<{ readonly byteLength: number; readonly digest: string }>;
33		readonly deletedAuthorSequenceRange: Readonly<{ readonly from: number; readonly through: number }> | null;
34		readonly observedLineage: DurableLineage;
35		readonly prunedThroughAuthorSequence: number;
36		readonly scope: DurableIssueScope;
37		readonly snapshotManifestDigest: string;
38	}
