40	export interface DurableIssuancePruningMaintenance {
41		inspectPruningState(scope: DurableIssueScope): Promise<DurableIssuancePruningState>;
42		pruneAuthenticatedSettledPrefix(input: unknown): Promise<DurableIssuancePruningReceipt>;
43		prunePublishedPrefix(input: unknown): Promise<DurableIssuancePruningReceipt>;
44	}
45	
46	const MAINTENANCE_REGISTRY = Symbol.for("@ts-drp/issuance-store/pruning-maintenance-v1");
47	interface MaintenanceRegistry {
48		bind(store: DurableIssuanceStore, maintenance: DurableIssuancePruningMaintenance): boolean;
49		resolve(store: DurableIssuanceStore): DurableIssuancePruningMaintenance | undefined;
50	}
51	type MaintenanceGlobal = typeof globalThis & {
52		[MAINTENANCE_REGISTRY]?: MaintenanceRegistry;
53	};
54	const maintenanceGlobal = globalThis as MaintenanceGlobal;
55	const maintenanceRegistry =
56		maintenanceGlobal[MAINTENANCE_REGISTRY] ??
57		((): MaintenanceRegistry => {
58			const maintenanceByStore = new WeakMap<DurableIssuanceStore, DurableIssuancePruningMaintenance>();
59			return Object.freeze({
60				bind(store: DurableIssuanceStore, maintenance: DurableIssuancePruningMaintenance): boolean {
61					if (maintenanceByStore.has(store)) return false;
62					maintenanceByStore.set(store, maintenance);
63					return true;
64				},
65				resolve(store: DurableIssuanceStore): DurableIssuancePruningMaintenance | undefined {
66					return maintenanceByStore.get(store);
67				},
68			});
69		})();
70	if (maintenanceGlobal[MAINTENANCE_REGISTRY] === undefined) {
71		Object.defineProperty(maintenanceGlobal, MAINTENANCE_REGISTRY, {
72			configurable: false,
73			enumerable: false,
74			value: maintenanceRegistry,
75			writable: false,
76		});
77	}
78	
79	/**
80	 * Binds a backend-owned maintenance capability to its exact ordinary facade.
81	 * This is a package-internal owner hook and is not re-exported by the ordinary store facade.
82	 * @param store - Exact frozen store facade.
83	 * @param maintenance - Backend-owned maintenance capability.
84	 * @returns Whether this was the first binding for the facade.
85	 */
86	export function bindDurableIssuancePruningMaintenance(
87		store: DurableIssuanceStore,
88		maintenance: DurableIssuancePruningMaintenance
89	): boolean {
90		return maintenanceRegistry.bind(store, maintenance);
91	}
92	
93	/**
94	 * Resolves maintenance for the exact facade without exposing mutation on it.
95	 * This is a package-internal owner hook and is not re-exported by the ordinary store facade.
96	 * @param store - Candidate ordinary store facade.
97	 * @returns Its identity-bound backend maintenance capability.
98	 */
99	export function durableIssuancePruningMaintenanceForStore(
100		store: DurableIssuanceStore
101	): DurableIssuancePruningMaintenance | undefined {
102		return maintenanceRegistry.resolve(store);
103	}
104	
105	/**
106	 * Tests whether one durable settlement plan permits authenticated prefix reclamation.
107	 * @param plan - The transactionally observed plan, or no durable plan.
108	 * @returns Whether every non-expiring source and the mandatory fence are linked.
109	 */
110	export function settlementPlanPermitsAuthenticatedPruning(
111		plan: Readonly<{
112			readonly entries: readonly Readonly<{
113				readonly disposition: "expire" | "manual-review" | "rebase" | "transform";
114				readonly replacementSequence: number | null;
115			}>[];
116			readonly fenceSequence: number | null;
117		}> | null
118	): boolean {
119		return (
120			plan !== null &&
121			plan.fenceSequence !== null &&
122			plan.entries.every(
123				(entry) =>
124					entry.disposition === "expire" || (entry.disposition !== "manual-review" && entry.replacementSequence !== null)
125			)
126		);
127	}
128	
129	/** Exact non-poisoning evidence that a caller-known ordinal was already pruned. */
130	export class DurableIssuanceRecordPrunedError extends Error implements DurableIssuanceError {
131		readonly authorSequence: number;
132		readonly code = "ISSUANCE_RECORD_PRUNED" as const;
133		readonly scope: DurableIssueScope;
134	
135		/**
136		 * Creates caller-known evidence for an ordinal already removed by pruning.
137		 * @param scope - Caller-known issuance scope.
138		 * @param authorSequence - Caller-known pruned ordinal.
139		 */
140		constructor(scope: DurableIssueScope, authorSequence: number) {
141			super("durable issuance record was pruned");
142			Object.defineProperty(this, "name", { configurable: true, value: "DurableIssuanceError" });
143			this.authorSequence = authorSequence;
144			this.scope = Object.freeze(copyDurableIssueScope(scope));
145		}
146	}
147	
148	function invalid(message: string): DurableIssuanceInvalidArgumentError {
149		return new DurableIssuanceInvalidArgumentError(message);
150	}
151	
152	function copyLineage(value: unknown): DurableLineage {
153		if (
154			!isClosedDurableIssuanceRecord(value, ["exhausted", "next"]) ||
155			typeof value.exhausted !== "boolean" ||
156			!isValidDurableAuthorSequence(value.next) ||
157			(value.exhausted && value.next !== Number.MAX_SAFE_INTEGER)
158		) {
159			throw invalid("expectedLineage must be an exact safe lineage record");
160		}
161		return { exhausted: value.exhausted, next: value.next };
162	}
163	
164	function copyWatermark(value: unknown): number | null {
165		if (value === null) return null;
166		if (!isValidDurableAuthorSequence(value)) throw invalid("pruning watermark must be null or a safe ordinal");
167		return value;
168	}
169	
170	/**
171	 * Validates and detaches one closed pruning request.
172	 * @param value - Untrusted request value.
173	 * @returns A detached validated pruning request.
174	 */
175	export function captureDurableIssuancePruningInput(value: unknown): DurableIssuancePruningInput {
176		try {
177			if (
178				!isClosedDurableIssuanceRecord(value, [
179					"closedEpoch",
180					"commitQcRef",
181					"expectedLineage",
182					"expectedPrunedThroughAuthorSequence",
183					"scope",
184					"snapshotManifestDigest",
185					"throughAuthorSequence",
186				]) ||
187				!isValidDurableAuthorSequence(value.closedEpoch) ||
188				!isValidDurableAuthorSequence(value.throughAuthorSequence) ||
189				!isClosedDurableIssuanceRecord(value.commitQcRef, ["byteLength", "digest"]) ||
190				!Number.isSafeInteger(value.commitQcRef.byteLength) ||
191				Number(value.commitQcRef.byteLength) < 1 ||
192				typeof value.commitQcRef.digest !== "string" ||
193				!HEX_DIGEST.test(value.commitQcRef.digest) ||
194				typeof value.snapshotManifestDigest !== "string" ||
195				!HEX_DIGEST.test(value.snapshotManifestDigest)
196			) {
197				throw invalid("pruning input must be one exact validated record");
198			}
199			assertDurableIssueScope(value.scope);
200			return {
201				closedEpoch: value.closedEpoch,
202				commitQcRef: { byteLength: Number(value.commitQcRef.byteLength), digest: value.commitQcRef.digest },
203				expectedLineage: copyLineage(value.expectedLineage),
204				expectedPrunedThroughAuthorSequence: copyWatermark(value.expectedPrunedThroughAuthorSequence),
205				scope: copyDurableIssueScope(value.scope),
206				snapshotManifestDigest: value.snapshotManifestDigest,
207				throughAuthorSequence: value.throughAuthorSequence,
208			};
209		} catch (error) {
210			if (error instanceof DurableIssuanceInvalidArgumentError) throw error;
211			throw invalid("pruning input could not be inspected as a closed record");
212		}
213	}
214	
215	/**
216	 * Compares two lineage CAS values.
217	 * @param left - First lineage value.
218	 * @param right - Second lineage value.
219	 * @returns Whether both lineage fields are equal.
220	 */
221	export function durableIssuanceLineagesEqual(left: DurableLineage, right: DurableLineage): boolean {
222		return left.exhausted === right.exhausted && left.next === right.next;
223	}
224	
225	/**
226	 * Tests whether a lineage has consumed an ordinal.
227	 * @param lineage - Observed durable lineage.
228	 * @param authorSequence - Ordinal to classify.
229	 * @returns Whether the lineage has consumed the ordinal.
230	 */
231	export function durableIssuanceLineageConsumed(lineage: DurableLineage, authorSequence: number): boolean {
232		return lineage.next > authorSequence || (lineage.exhausted && lineage.next === authorSequence);
233	}
234	
235	/**
236	 * Tests the explicit inclusive pruning-watermark relation.
237	 * @param watermark - Inclusive watermark or no pruning state.
238	 * @param authorSequence - Ordinal to classify.
239	 * @returns Whether the ordinal is at or below a real watermark.
240	 */
241	export function durableIssuanceAddressIsPruned(watermark: number | null, authorSequence: number): boolean {
242		return watermark !== null && authorSequence <= watermark;
243	}
244	
245	/**
246	 * Decodes only the closed v3 vertex fields needed by the issuance owner.
247	 * @param canonicalPreimageBytes - Canonical preimage bytes to decode.
248	 * @param scope - Expected issuance scope.
249	 * @param authorSequence - Expected issuance ordinal.
250	 * @returns The validated epoch or `undefined` for any mismatch.
251	 */
252	export function decodeDurableIssuancePreimage(
253		canonicalPreimageBytes: Uint8Array,
254		scope: DurableIssueScope,
255		authorSequence: number
256	): Readonly<{ readonly epoch: number }> | undefined {
257		try {
258			const decoded: unknown = decodeCanonical(canonicalPreimageBytes);
259			if (typeof decoded !== "object" || decoded === null || Array.isArray(decoded)) return undefined;
260			const record = decoded as Record<string, unknown>;
261			if (
262				record.kind === "drp-vertex" &&
263				record.protocolMajor === 3 &&
264				isValidDurableAuthorSequence(record.epoch) &&
265				record.authorSequence === authorSequence &&
266				record.author === scope.author &&
267				record.objectId === scope.objectId
268			) {
269				return Object.freeze({ epoch: record.epoch });
270			}
271			return undefined;
272		} catch {
273			return undefined;
274		}
275	}
276	
277	/**
278	 * Creates a deeply detached immutable pruning-state observation.
279	 * @param scope - Observed issuance scope.
280	 * @param lineage - Observed lineage CAS value.
281	 * @param prunedThroughAuthorSequence - Observed inclusive watermark.
282	 * @returns A frozen detached observation.
283	 */
284	export function createDurableIssuancePruningState(
285		scope: DurableIssueScope,
286		lineage: DurableLineage,
287		prunedThroughAuthorSequence: number | null
288	): DurableIssuancePruningState {
289		return Object.freeze({
290			lineage: Object.freeze({ ...lineage }),
291			prunedThroughAuthorSequence,
292			scope: Object.freeze(copyDurableIssueScope(scope)),
293		});
294	}
295	
296	/**
297	 * Creates a deeply detached immutable pruning receipt.
298	 * @param input - Captured pruning request.
299	 * @param observedLineage - Transactionally observed lineage.
300	 * @param deletedFrom - First removed ordinal or `null` for replay.
301	 * @returns A frozen detached receipt.
302	 */
303	export function createDurableIssuancePruningReceipt(
304		input: DurableIssuancePruningInput,
305		observedLineage: DurableLineage,
306		deletedFrom: number | null
307	): DurableIssuancePruningReceipt {
308		return Object.freeze({
309			closedEpoch: input.closedEpoch,
310			commitQcRef: Object.freeze({ ...input.commitQcRef }),
311			deletedAuthorSequenceRange:
312				deletedFrom === null ? null : Object.freeze({ from: deletedFrom, through: input.throughAuthorSequence }),
313			observedLineage: Object.freeze({ ...observedLineage }),
314			prunedThroughAuthorSequence: input.throughAuthorSequence,
315			scope: Object.freeze(copyDurableIssueScope(input.scope)),
316			snapshotManifestDigest: input.snapshotManifestDigest,
317		});
318	}
319	
320	/**
321	 * Creates frozen non-poisoning evidence for a caller-known pruned address.
322	 * @param scope - Caller-known issuance scope.
323	 * @param authorSequence - Caller-known pruned ordinal.
324	 * @returns A closed frozen pruned-address error.
325	 */
326	export function createDurableIssuanceRecordPrunedError(
327		scope: DurableIssueScope,
328		authorSequence: number
329	): DurableIssuanceRecordPrunedError {
330		return Object.freeze(new DurableIssuanceRecordPrunedError(scope, authorSequence));
331	}
